"""Minimal JEV (TypeSafe System One compatible) client demo.

Usage:
    set JEV_BASE_URL=https://claudeme.org      (sub4api relay, or http://<js4090>:8800 direct)
    set JEV_API_KEY=sk-...                     (a sub4api key whose group serves jev-latest)
    python jev_systemone_demo.py
"""

import json
import os
import urllib.error
import urllib.request

BASE_URL = os.environ.get("JEV_BASE_URL", "https://claudeme.org")
API_KEY = os.environ.get("JEV_API_KEY", "")
if not API_KEY:
    raise SystemExit("set JEV_API_KEY first (a sub4api key whose group serves jev-latest)")


def systemone(state, questions, model="jev-latest", timeout=30):
    body = json.dumps(
        {"model": model, "state": state, "questions": questions}, ensure_ascii=False
    ).encode("utf-8")
    request = urllib.request.Request(
        BASE_URL + "/v1/systemone",
        data=body,
        headers={
            "Authorization": "Bearer " + API_KEY,
            "Content-Type": "application/json",
            # Cloudflare rejects urllib's default "Python-urllib/x.y" (error 1010).
            "User-Agent": "jev-systemone-demo/1.0",
        },
    )
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            return json.load(response)
    except urllib.error.HTTPError as error:
        raise SystemExit(
            f"HTTP {error.code}: {error.read().decode('utf-8', 'replace')}")


def is_true(state, question):
    """Ask one yes/no question about a JSON/text state; return (bool, probability)."""
    answer = systemone(
        state, {"q": {"type": "noul", "instructions": question}})
    noul = answer["answers"]["q"]["noul"]
    return noul >= 0.5, noul


